-- neighbourgoods-market-woodstock (researched)
UPDATE businesses SET description = 'Neighbourgoods Market is a weekly food, drink and designer market held at The Old Biscuit Mill, a former biscuit factory on Albert Road in Woodstock. Running for almost two decades, it was Cape Town''s original gathering place for small, creative traders and still draws a buzzing community of stallholders and visitors on Saturdays.

The market''s street-food stalls cover a wide spread of cuisines, from flammkuchen, churros, pasta and shakshuka to Korean delicacies, Swahili doughnuts, paella and shisa nyama, with vegan, halaal and sugar-free options catered for throughout. Entry is free, and the market suits a weekend outing for anyone who wants to graze between stalls, browse design and craft traders, and soak up Woodstock''s creative-community atmosphere.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://insideguide.co.za/cape-town/things-to-do/neighbourgoods-market/'), description_enriched_at = datetime('now') WHERE slug = 'neighbourgoods-market-woodstock' AND description = 'Neighbourgoods Market is a weekly food, drink and designer market held at The Old Biscuit Mill in Woodstock on Saturdays, with free entry.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
