UPDATE businesses SET description = 'Newport Market & Deli is an artisanal sourdough bakery, deli and café on Beach Road in Mouille Point, founded in December 1997. What began as a small corner deli with a Californian-inspired, street-café style has grown into a Cape Town institution that now includes a sit-down restaurant, a delicatessen stocking local and imported products, a cold-pressed juice and smoothie bar, and its own sourdough bakery.

Staff numbers have grown from four at the outset to more than 60 today, and the team hand-makes its sourdough bread, pastries and other goods on the premises under its "Naturally Newport" ethos. The deli and restaurant both open daily from 6:30am, and the spot is known for its sea views on Beach Road. It suits anyone looking for all-day dining, fresh bread or deli groceries close to the Mouille Point promenade.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.newportdeli.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'newport-market-and-deli-mouille-point' AND description = 'Newport Market & Deli is a deli and cafe on Beach Road, Mouille Point, known for its sea views, fresh food and coffee.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
